inline constexpr std::string_view glsl_fragment = R"SHADER(
#version 450
layout(location = 0) in vec2  v_local;
layout(location = 1) in vec2  v_norm;
layout(location = 2) in vec4  v_color;
layout(location = 3) in vec4  v_color2;
layout(location = 4) in vec4  v_radii;
layout(location = 5) in vec4  v_axis;
layout(location = 6) in vec4  v_params;
layout(location = 7) in vec2  v_uv;
layout(location = 8) flat in uvec4 v_meta;
layout(location = 9) in vec2  v_half;

layout(set = 0, binding = 0) uniform sampler2D u_atlas;
layout(set = 0, binding = 1) uniform sampler2D u_color_atlas;
layout(set = 0, binding = 2) uniform sampler2D u_capture;
layout(set = 0, binding = 3) uniform sampler2D u_texture;

layout(location = 0) out vec4 o_color;

// ── everything below is GENERATED from include/mayag/render/kernel.hpp ──
// Do not edit: run tools/gen_shaders.py (CMake does this automatically).

struct Fragment {
    vec2 local; vec2 norm; vec2 frag; vec2 half_size; vec2 uv;
    vec4 color; vec4 color2; vec4 radii; vec4 axis; vec4 params;
    float px; uint kind; uint flags;
};
struct Shaded { vec4 color; bool discarded; };

// Texture access — the only backend-specific part of the fragment program.
float env_atlas_r(vec2 uv)     { return texture(u_atlas, uv).r; }
vec4  env_atlas_rgba(vec2 uv)  { return texture(u_color_atlas, uv); }
vec4  env_capture(vec2 uv)     { return texture(u_capture, uv); }
vec4  env_texture(vec2 uv)     { return texture(u_texture, uv); }
vec2  env_capture_size()       { return vec2(textureSize(u_capture, 0)); }
float k_pi     = 3.14159265;
float k_two_pi = 6.28318531;

// ShapeKind, mirrored as plain constants so the transpiler emits them as-is.
uint KIND_ROUNDED_BOX = 0u;
uint KIND_CIRCLE      = 1u;
uint KIND_RING        = 2u;
uint KIND_LINE        = 3u;
uint KIND_GLYPH       = 4u;
uint KIND_TEXTURE     = 5u;
uint KIND_SHADOW      = 6u;
uint KIND_ARC         = 7u;
uint KIND_COLOR_GLYPH = 8u;
uint KIND_BACKDROP    = 9u;

uint FLAG_GRADIENT  = 1u;
uint FLAG_RADIAL    = 2u;
uint FLAG_ANGULAR   = 4u;
uint FLAG_SRGB      = 8u;
uint FLAG_STROKE    = 16u;
uint FLAG_INSET     = 32u;
uint FLAG_DASHED    = 64u;
uint FLAG_GLYPH_SDF = 128u;

// ── signed distance fields ──────────────────────────────────────────────
// Negative inside, zero on the boundary, positive outside, unit gradient.
// That last property is why `coverage()` is a correct analytic antialias at
// any scale, and why mayag needs no MSAA and no supersampling.

/// Rounded box with per-corner radii (tl, tr, br, bl). `p` is relative to the
/// box CENTRE, `b` is the half-size. Inigo Quilez's formulation.
float rounded_box(vec2 p, vec2 b, vec4 radii)  {
    float r = (p.x > 0.0) ? ((p.y > 0.0) ? radii.z : radii.y)
                         : ((p.y > 0.0) ? radii.w : radii.x);
    r = min(r, min(b.x, b.y));
    vec2 q = vec2(abs(p.x) - b.x + r, abs(p.y) - b.y + r);
    vec2 qp = vec2(max(q.x, 0.0), max(q.y, 0.0));
    return min(max(q.x, q.y), 0.0) + length(qp) - r;
}

/// Circle of radius `r` centred at the origin.
float circle(vec2 p, float r)  { return length(p) - r; }

/// Annulus: a ring of radius `r` and thickness `t`.
float ring(vec2 p, float r, float t)  {
    return abs(length(p) - r) - t * 0.5;
}

/// Capsule between `a` and `b` with the given thickness.
float segment(vec2 p, vec2 a, vec2 b, float thickness)  {
    vec2 pa = vec2(p.x - a.x, p.y - a.y);
    vec2 ba = vec2(b.x - a.x, b.y - a.y);
    float  h  = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
    return length(vec2(pa.x - ba.x * h, pa.y - ba.y * h)) - thickness * 0.5;
}

/// Partial ring. `start`/`sweep` are radians; a full sweep degenerates to ring.
float arc(vec2 p, float r, float thickness, float start, float sweep)  {
    float ring_d = ring(p, r, thickness);
    if (sweep >= k_two_pi) return ring_d;
    float ang = mod(atan(p.y, p.x) - start, k_two_pi);
    if (ang <= sweep) return ring_d;
    vec2 e0 = vec2(r * cos(start), r * sin(start));
    vec2 e1 = vec2(r * cos(start + sweep), r * sin(start + sweep));
    float  d0 = length(vec2(p.x - e0.x, p.y - e0.y));
    float  d1 = length(vec2(p.x - e1.x, p.y - e1.y));
    return min(d0, d1) - thickness * 0.5;
}

/// Hollow out a field: turns a filled shape into a stroke of width `w`.
float outline(float d, float w)  { return abs(d) - w * 0.5; }

/// Analytic coverage of a distance field over a pixel footprint `px`.
float coverage(float d, float px)  {
    float w = max(px, 1e-6) * 0.5;
    return smoothstep(w, -w, d);
}

/// A blurred box is the same field, softened — no blur pass, no downsample.
float shadow_coverage(float d, float blur)  {
    if (blur <= 0.0) return d <= 0.0 ? 1.0 : 0.0;
    return smoothstep(blur, -blur, d);
}

// ── perceptual colour ───────────────────────────────────────────────────
// Oklab/Oklch (Björn Ottosson). Gradients interpolate in POLAR Oklch: a
// straight Cartesian line between opposite hues passes near the neutral axis
// and desaturates the midpoint almost as badly as an RGB lerp.

vec4 linear_to_oklab(vec4 c)  {
    float l = 0.4122214708 * c.x + 0.5363325363 * c.y + 0.0514459929 * c.z;
    float m = 0.2119034982 * c.x + 0.6806995451 * c.y + 0.1073969566 * c.z;
    float s = 0.0883024619 * c.x + 0.2817188376 * c.y + 0.6299787005 * c.z;
    float l_ = pow(max(l, 0.0), 1.0 / 3.0);
    float m_ = pow(max(m, 0.0), 1.0 / 3.0);
    float s_ = pow(max(s, 0.0), 1.0 / 3.0);
    return vec4(0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_,
                1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_,
                0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_,
                0.0);
}

vec4 oklab_to_linear(vec4 lab)  {
    float l_ = lab.x + 0.3963377774 * lab.y + 0.2158037573 * lab.z;
    float m_ = lab.x - 0.1055613458 * lab.y - 0.0638541728 * lab.z;
    float s_ = lab.x - 0.0894841775 * lab.y - 1.2914855480 * lab.z;
    float l = l_ * l_ * l_;
    float m = m_ * m_ * m_;
    float s = s_ * s_ * s_;
    return vec4(max(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s, 0.0),
                max(-1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s, 0.0),
                max(-0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s, 0.0),
                0.0);
}

/// Interpolate two LINEAR PREMULTIPLIED colours through Oklch.
vec4 mix_oklch(vec4 a, vec4 b, float t)  {
    // Un-premultiply; interpolating premultiplied chroma is meaningless.
    float aa = a.w > 1e-6 ? a.w : 1.0;
    float ab = b.w > 1e-6 ? b.w : 1.0;
    vec4 ca = a.w > 1e-6 ? vec4(a.x / aa, a.y / aa, a.z / aa, 0.0) : vec4(0, 0, 0, 0);
    vec4 cb = b.w > 1e-6 ? vec4(b.x / ab, b.y / ab, b.z / ab, 0.0) : vec4(0, 0, 0, 0);

    vec4 la = linear_to_oklab(ca);
    vec4 lb = linear_to_oklab(cb);

    float chroma_a = length(vec2(la.y, la.z));
    float chroma_b = length(vec2(lb.y, lb.z));
    float ha = atan(la.z, la.y);
    float hb = atan(lb.z, lb.y);

    // Shortest way around the hue circle.
    float dh = hb - ha;
    if (dh > k_pi) dh = dh - k_two_pi;
    if (dh < -k_pi) dh = dh + k_two_pi;

    float L      = mix(la.x, lb.x, t);
    float chroma = mix(chroma_a, chroma_b, t);
    float hue    = ha + dh * t;
    float alpha  = mix(a.w, b.w, t);

    vec4 lin = oklab_to_linear(
        vec4(L, chroma * cos(hue), chroma * sin(hue), 0.0));
    return vec4(lin.x * alpha, lin.y * alpha, lin.z * alpha, alpha);   // re-premultiply
}

/// sRGB -> linear, the exact piecewise transfer.
///
/// The kernel never ENCODES (the framebuffer does that), but it must DECODE:
/// a user image arrives sRGB-encoded, and multiplying it into a linear
/// premultiplied colour without decoding first is a gamma error that shows up
/// as a tinted image being too bright.
float srgb_to_linear(float c)  {
    if (c <= 0.04045) return c / 12.92;
    return pow((c + 0.055) / 1.055, 2.4);
}

// ── text ────────────────────────────────────────────────────────────────
//
// Stem darkening. Coverage-antialiased glyphs look too THIN when light text
// sits on a dark background, because the eye integrates a light stroke on
// dark more generously than the linear coverage says. FreeType calls this
// stem darkening; Apple and Skia apply a comparable gamma. Applied to
// COVERAGE, not colour, so it can never shift hue.
//
// This lives in the kernel — not in one backend — precisely because it is a
// LOOK decision. It used to exist only in the software rasteriser, which is
// why GPU text could never match the reference at any tolerance.
float text_gamma_light = 0.80;
float text_gamma_dark  = 1.05;

float apply_text_gamma(float cov, vec4 premul_color)  {
    if (cov <= 0.0) return cov;
    if (cov >= 1.0) return cov;
    float a = premul_color.w > 1e-4 ? premul_color.w : 1.0;
    float lum = (0.2126 * premul_color.x +
                     0.7152 * premul_color.y +
                     0.0722 * premul_color.z) / a;
    // Blend between the two exponents by how light the text is, so a mid-grey
    // label does not jump discontinuously between regimes.
    float t = clamp(lum * 2.0, 0.0, 1.0);
    float gamma = mix(text_gamma_dark, text_gamma_light, t);
    return pow(cov, gamma);
}

/// Fallback half-width of the SDF threshold band, in normalised field units,
/// used when the glyph emitter supplied none. It must be at least half the
/// field's change across ONE texel or the smoothstep lands entirely between
/// samples and every edge snaps hard. At the default 48 px raster and 6 px
/// spread one texel step changes the field by ~0.082, so this gives a ~2-texel
/// ramp: a clean edge without the blur a wider band would introduce.
float sdf_edge_fallback = 0.09;

float shape_coverage(Fragment f)  {
    if (f.kind == KIND_ROUNDED_BOX || f.kind == KIND_TEXTURE) {
        float d = rounded_box(f.local, f.half_size, f.radii);
        if ((f.flags & FLAG_STROKE) != 0u) d = outline(d + f.params.x * 0.5, f.params.x);
        return coverage(d, f.px);
    }
    if (f.kind == KIND_CIRCLE) {
        return coverage(circle(f.local, min(f.half_size.x, f.half_size.y)), f.px);
    }
    if (f.kind == KIND_RING) {
        return coverage(ring(f.local, min(f.half_size.x, f.half_size.y), f.params.x), f.px);
    }
    if (f.kind == KIND_ARC) {
        return coverage(arc(f.local, min(f.half_size.x, f.half_size.y),
                            f.params.x, f.params.y, f.params.z), f.px);
    }
    if (f.kind == KIND_LINE) {
        return coverage(segment(f.frag, vec2(f.axis.x, f.axis.y),
                                vec2(f.axis.z, f.axis.w), f.params.x), f.px);
    }
    if (f.kind == KIND_SHADOW) {
        if ((f.flags & FLAG_INSET) != 0u) {
            // An INNER shadow lives inside the shape: darkness where the
            // shadow's box -- offset by (params.z, params.w) and shrunk by
            // the spread -- has NOT reached, clipped to the shape itself.
            // (It used to be 1 - drop shadow over the whole grown quad,
            // which painted a dark slab AROUND every inner-shadowed box.)
            float clip = coverage(rounded_box(f.local, f.half_size, f.radii), f.px);
            vec2 off = vec2(f.params.z, f.params.w);
            vec2 inner = vec2(max(f.half_size.x - f.params.y, 0.0), max(f.half_size.y - f.params.y, 0.0));
            float d = rounded_box(f.local - off, inner, f.radii);
            return (1.0 - shadow_coverage(d, max(f.params.x, 0.01))) * clip;
        }
        float d = rounded_box(f.local, f.half_size, f.radii);
        return shadow_coverage(d, max(f.params.x, 0.01));
    }
    return coverage(rounded_box(f.local, f.half_size, f.radii), f.px);
}

/// Resolve the fill colour, applying any gradient. LINEAR PREMULTIPLIED in,
/// LINEAR PREMULTIPLIED out.
vec4 fill_color(Fragment f)  {
    if ((f.flags & FLAG_GRADIENT) == 0u) return f.color;

    float t = 0.0;
    if ((f.flags & FLAG_RADIAL) != 0u) {
        vec2 d = vec2(f.norm.x - f.axis.x, f.norm.y - f.axis.y);
        t = clamp(length(d) / max(f.params.z, 1e-4), 0.0, 1.0);
    } else if ((f.flags & FLAG_ANGULAR) != 0u) {
        vec2 d = vec2(f.norm.x - f.axis.x, f.norm.y - f.axis.y);
        t = clamp((atan(d.y, d.x) + k_pi) / k_two_pi, 0.0, 1.0);
    } else {
        vec2 ab = vec2(f.axis.z - f.axis.x, f.axis.w - f.axis.y);
        vec2 pa = vec2(f.norm.x - f.axis.x, f.norm.y - f.axis.y);
        t = clamp(dot(pa, ab) / max(dot(ab, ab), 1e-6), 0.0, 1.0);
    }

    // Perceptual (Oklch) by default; FLAG_SRGB opts into the naive ramp for
    // designs authored against CSS.
    if ((f.flags & FLAG_SRGB) != 0u) {
        return vec4(mix(f.color.x, f.color2.x, t), mix(f.color.y, f.color2.y, t),
                    mix(f.color.z, f.color2.z, t), mix(f.color.w, f.color2.w, t));
    }
    return mix_oklch(f.color, f.color2, t);
}

/// Shade one fragment. THE function — every backend's inner loop ends here.
Shaded shade(Fragment f)  {
    Shaded result; result.discarded = false;

    // ── colour glyphs (emoji): straight RGBA, tinted only by opacity ──
    if (f.kind == KIND_COLOR_GLYPH) {
        vec4 t = env_atlas_rgba(f.uv);
        float  a = t.w * f.color.w;
        if (a <= 0.001) { result.discarded = true; return result; }
        result.color = vec4(t.x * a, t.y * a, t.z * a, a);
        return result;
    }

    // ── frosted glass: blur the mid-frame capture behind this shape ──
    if (f.kind == KIND_BACKDROP) {
        float bd_cov = coverage(rounded_box(f.local, f.half_size, f.radii), f.px);
        if (bd_cov <= 0.001) { result.discarded = true; return result; }
        float r = max(f.params.x, 0.0);
        vec4 sum = vec4(0, 0, 0, 0);
        float  wsum = 0.0;
        for (int oy = -2; oy <= 2; ++oy) {
            for (int ox = -2; ox <= 2; ++ox) {
                float fx = float(ox) * 0.5;
                float fy = float(oy) * 0.5;
                float w  = exp(-(fx * fx + fy * fy) * 2.0);
                vec2 uv = vec2(
                    (f.frag.x + float(ox) * r * 0.5) / env_capture_size().x,
                    (f.frag.y + float(oy) * r * 0.5) / env_capture_size().y);
                vec4 s = env_capture(uv);
                sum.x += s.x * w; sum.y += s.y * w; sum.z += s.z * w;
                wsum += w;
            }
        }
        float inv = 1.0 / max(wsum, 1e-4);
        vec4 c = vec4(sum.x * inv, sum.y * inv, sum.z * inv, 0.0);
        float sat = f.params.y, bright = f.params.z;
        float luma = 0.2126 * c.x + 0.7152 * c.y + 0.0722 * c.z;
        c = vec4(max(mix(luma, c.x, sat) * bright, 0.0),
                 max(mix(luma, c.y, sat) * bright, 0.0),
                 max(mix(luma, c.z, sat) * bright, 0.0), 0.0);
        result.color = vec4(c.x * bd_cov, c.y * bd_cov, c.z * bd_cov, bd_cov);
        return result;
    }

    // ── coverage ────────────────────────────────────────────────────
    float cov;
    if (f.kind == KIND_GLYPH) {
        float raw = env_atlas_r(f.uv);
        if ((f.flags & FLAG_GLYPH_SDF) != 0u) {
            // Distance-field entry: 0.5 is the edge. The half-band comes from
            // the glyph emitter (params.x), which derives it from the SDF
            // spread and the raster->display scale. Using a derivative here
            // instead would over-estimate the ramp on a magnified, bilinearly
            // sampled field and bloom every glyph into a grey halo.
            float band = f.params.x > 0.0 ? f.params.x : sdf_edge_fallback;
            cov = smoothstep(0.5 - band, 0.5 + band, raw);
        } else {
            cov = raw;   // bitmap entry: already coverage
        }
        cov = apply_text_gamma(cov, f.color);
    } else {
        cov = shape_coverage(f);
    }

    if (cov <= 0.001) { result.discarded = true; return result; }

    vec4 color = fill_color(f);

    if (f.kind == KIND_TEXTURE) {
        // A user image, modulated by the node's colour so `image(id) | fg(c)`
        // tints and `| opacity(a)` fades. The sample is straight (not
        // premultiplied) sRGB-encoded RGBA; the shader's own colour is linear
        // premultiplied, so decode before multiplying or a tinted image comes
        // out with the wrong gamma.
        vec4 t = env_texture(f.uv);
        vec4 lin = vec4(srgb_to_linear(t.x), srgb_to_linear(t.y),
                              srgb_to_linear(t.z), t.w);
        color = vec4(color.x * lin.x, color.y * lin.y,
                     color.z * lin.z, color.w * lin.w);
    }

    // LINEAR PREMULTIPLIED. No transfer function here, ever: the software path
    // composites into a linear framebuffer and encodes once at the end, and the
    // GPU path renders into an _SRGB attachment so the hardware decodes, blends
    // in linear, and encodes on store. Both blend coverage in linear light.
    result.color = vec4(color.x * cov, color.y * cov, color.z * cov, color.w * cov);
    return result;
}


void main() {
    Fragment f;
    f.local  = v_local;
    f.norm   = v_norm;
    f.frag   = gl_FragCoord.xy;
    f.half_size = v_half;
    f.uv     = v_uv;
    f.color  = v_color;
    f.color2 = v_color2;
    f.radii  = v_radii;
    f.axis   = v_axis;
    f.params = v_params;
    // Pixel footprint from screen-space derivatives: this is what makes the
    // antialiasing correct under arbitrary transform and zoom. It is the one
    // quantity the CPU computes differently (it knows its own scale), which is
    // why it is an INPUT to the kernel rather than something the kernel derives.
    f.px     = max(length(fwidth(v_local)), 1e-6);
    f.kind   = v_meta.x;
    f.flags  = v_meta.y;

    Shaded s = shade(f);
    if (s.discarded) discard;
    o_color = s.color;
}

)SHADER";

